import { MAPS } from '/tmp/maps_v.mjs';
const m = MAPS.bastion;
const solids = m.BOXES.filter(b => b[6] !== 4 && b[6] !== 5);
let fails = 0;
const fail = s => { console.log('FAIL', s); fails++; };

// box count budget
if (m.BOXES.length > 64) fail(`too many boxes: ${m.BOXES.length}`);
console.log('boxes:', m.BOXES.length);

// ground height at (x,z): top of highest solid whose footprint contains point and top <= 2.6
function groundAt(x, z) {
  let g = -99;
  for (const b of solids) {
    if (x >= b[0] && x <= b[3] && z >= b[2] && z <= b[5] && b[4] <= 2.6) g = Math.max(g, b[4]);
  }
  return g;
}
// clearance: standing capsule at ground height must not clip solids
function clear(x, z, label) {
  const g = groundAt(x, z);
  if (g < -3) { fail(`${label} (${x},${z}) no ground`); return; }
  for (const b of solids) {
    // expand by player radius .35 + margin
    if (x > b[0] - 0.5 && x < b[3] + 0.5 && z > b[2] - 0.5 && z < b[5] + 0.5) {
      // overlap standing band above ground
      if (b[4] > g + 0.05 && b[1] < g + 1.8) fail(`${label} (${x},${z}) clips box [${b}] ground=${g}`);
    }
  }
}
for (let i = 0; i < m.WAYPOINTS.length; i++) clear(m.WAYPOINTS[i].x, m.WAYPOINTS[i].z, 'wp' + i);
for (const s of m.BOT_SPAWNS) clear(s.x, s.z, 'botspawn');
for (const s of m.DM_SPAWNS) clear(s.x, s.z, 'dmspawn');
clear(m.PLAYER_SPAWN.x, m.PLAYER_SPAWN.z, 'playerspawn');

// connectivity
const adj = m.WAYPOINTS.map(() => []);
for (const [a, b] of m.WAYPOINT_EDGES) { adj[a].push(b); adj[b].push(a); }
const seen = new Set([0]); const q = [0];
while (q.length) { const n = q.shift(); for (const x of adj[n]) if (!seen.has(x)) { seen.add(x); q.push(x); } }
if (seen.size !== m.WAYPOINTS.length) fail(`graph disconnected: ${seen.size}/${m.WAYPOINTS.length}`);

// edge walk: sample along each edge — ground must never drop below start band
// (no falling into trench) and standing band must be clear of walls
for (const [a, b] of m.WAYPOINT_EDGES) {
  const A = m.WAYPOINTS[a], B = m.WAYPOINTS[b];
  const steps = Math.ceil(Math.hypot(B.x - A.x, B.z - A.z) * 2);
  for (let i = 0; i <= steps; i++) {
    const x = A.x + (B.x - A.x) * i / steps;
    const z = A.z + (B.z - A.z) * i / steps;
    const g = groundAt(x, z);
    if (g < -0.7) { fail(`edge ${a}-${b} falls into trench at (${x.toFixed(1)},${z.toFixed(1)}) g=${g}`); break; }
    for (const bx of solids) {
      if (x > bx[0] - 0.3 && x < bx[3] + 0.3 && z > bx[2] - 0.3 && z < bx[5] + 0.3) {
        if (bx[4] > g + 0.05 && bx[1] < g + 1.6) { fail(`edge ${a}-${b} blocked by [${bx.slice(0,7)}] at (${x.toFixed(1)},${z.toFixed(1)})`); i = steps + 1; break; }
      }
    }
  }
}
console.log(fails ? `${fails} FAILURES` : 'BASTION OK');
process.exit(fails ? 1 : 0);
